import 'package:flutter/material.dart';
import '../../data/app_store.dart';
class JournalPage extends StatefulWidget{final AppStore store;const JournalPage({super.key,required this.store});@override State<JournalPage>createState()=>_S();}
class _S extends State<JournalPage>{final c=TextEditingController();Future<void>save()async{if(c.text.trim().isEmpty)return;widget.store.data['journal'].add({'id':'j_'+DateTime.now().microsecondsSinceEpoch.toString(),'text':c.text.trim(),'createdAt':DateTime.now().toIso8601String(),'wheelIds':[]});await widget.store.save();c.clear();setState((){});}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Дневник')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:c,maxLines:6,decoration:const InputDecoration(hintText:'Что происходит? Что вы заметили?')),const SizedBox(height:10),FilledButton(onPressed:save,child:const Text('Сохранить запись')),Expanded(child:ListView(children:[...((widget.store.data['journal'] as List?)??[]).reversed.map((e)=>Card(child:ListTile(title:Text(e['text']),subtitle:Text(e['createdAt']))))]))]));}
